    @Test func compressed() {
        let mismatches = Mismatches("portCompressedU64InVectorCode")
        let aInputs = Inputs.vectors(H.self, seed: 0x7137_F0D0_754F_B645)
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0x7137_EFD0_754F_B492)
        for (a, mask) in everyPair(aInputs, maskInputs) {
            let port = { () -> SIMD<UInt64> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<UInt64>.self, capacity: 1) { result in
                    unsafe portCompressedU64InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<UInt64> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<UInt64>.self, capacity: 1) { result in
                    unsafe highwayCompressedU64InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let checkedLanes =
                HighwayReference.compressTailIsDeterministicU64() ? H.laneCount : H.trueCount(mask)
            mismatches.check(
                (0..<checkedLanes).map { port.simd[$0] },
                (0..<checkedLanes).map { reference.simd[$0] },
                "a: \(describe(a)), mask: \(describe(mask))"
            )
        }
        mismatches.record()
    }

